'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64Array = require( '@stdlib/array/complex64' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var EPS = require( '@stdlib/constants/float32/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var ctrsm = require( './../lib' );


// FUNCTIONS //

/**
* Tests for element-wise approximate equality.
*
* @private
* @param {Object} t - test object
* @param {Complex64Array} actual - actual array
* @param {Complex64Array} expected - expected array
* @param {number} rtol - relative tolerance
*/
function isApprox( t, actual, expected, rtol ) {
	var delta;
	var tol;
	var i;

	t.strictEqual( actual.length, expected.length, 'has expected length' );
	for ( i = 0; i < actual.length; i++ ) {
		if ( realf( actual.get( i ) ) === realf( expected.get( i ) ) && imagf( actual.get( i ) ) === imagf( expected.get( i ) ) ) {
			t.pass( 'elements ' + i + ' are equal' );
		} else {
			delta = abs( realf( actual.get( i ) ) - realf( expected.get( i ) ) );
			tol = rtol * abs( realf( expected.get( i ) ) );
			t.ok( delta <= tol, 'within tolerance. actual (re): ' + realf( actual.get( i ) ) + '. expected (re): ' + realf( expected.get( i ) ) + '. tol: ' + tol + '. delta: ' + delta + '.' );

			delta = abs( imagf( actual.get( i ) ) - imagf( expected.get( i ) ) );
			tol = rtol * abs( imagf( expected.get( i ) ) );
			t.ok( delta <= tol, 'within tolerance. actual (im): ' + imagf( actual.get( i ) ) + '. expected (im): ' + imagf( expected.get( i ) ) + '. tol: ' + tol + '. delta: ' + delta + '.' );
		}
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctrsm, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an ndarray method', function test( t ) {
	t.strictEqual( typeof ctrsm.ndarray, 'function', 'has ndarray method' );
	t.end();
});

tape( 'the function throws an error if provided an invalid order argument', function test( t ) {
	var alpha = new Complex64( 1.0, 0.0 );
	var A = new Complex64Array( [ 1.0, 0.0 ] );
	var B = new Complex64Array( [ 1.0, 0.0 ] );
	t.throws( badValue, TypeError, 'throws an error' );
	t.end();

	function badValue() {
		ctrsm( 'beep', 'left', 'upper', 'no-transpose', 'non-unit', 1, 1, alpha, A, 1, B, 1 );
	}
});

