tape( 'the function returns B unchanged if M is zero (row-major)', function test( t ) {
	var expected;
	var alpha;
	var out;
	var A;
	var B;

	A = new Complex64Array( [] );
	B = new Complex64Array( [] );
	alpha = new Complex64( 1.0, 0.0 );
	expected = new Complex64Array( [] );

	out = ctrsm( 'row-major', 'left', 'upper', 'no-transpose', 'non-unit', 0, 1, alpha, A, 1, B, 1 );

	t.strictEqual( out, B, 'returns B' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

